//! 🧪️ Actual allocation and post failures keep their original owner.
use super::*;
use super::super::NativeAllocationEvent;use crate::eff;
use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering};
fn close<T:crate::retirement::RetireOwned>(value:T){eff::close(value);}
#[test]
fn slot_posts_real_allocator_failure_and_retains_post_refusal(){
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../🛬️decode/🛂️allocation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let case=fixture["allocationSettlement"].as_array().unwrap().iter().find(|row|row["name"]=="allocationAndPostRefused").unwrap();let prior=case["prior"].as_u64().unwrap()as usize;let request=case["requested"].as_u64().unwrap()as usize;let admitted=AtomicUsize::new(0);let posted=AtomicUsize::new(usize::MAX);let deny=AtomicBool::new(false);let port=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(quote)=>{assert_eq!(quote.owned_bytes,admitted.load(Ordering::Relaxed));Ok(())},NativeAllocationEvent::Post{request,actual}=>{admitted.store(request.next_owned_bytes,Ordering::Relaxed);posted.store(actual,Ordering::Relaxed);if deny.load(Ordering::Relaxed){Err(ValueError::literal(ValueRefusalKind::Canceled,"post refused"))}else{Ok(())}},NativeAllocationEvent::Cancel(_)=>if deny.load(Ordering::Relaxed){Err(ValueError::literal(ValueRefusalKind::Canceled,"cancel refused"))}else{Ok(())}};let mut progress=|_|true;let mut authority=crate::NativeAllocationAuthority::new(eff::Port(port));authority.with_send_loan(&mut (),|port_loan|{let mut native=NativeEncodeControl::new_forwarded(prior+request,&mut progress,port_loan);let mut prior_owner=Vec::<u8>::new();let mut unwind=None;let mut prior_actual=None;native.allocate_vec_into(prior,&mut prior_owner,&mut prior_actual,&mut unwind).unwrap();deny.store(true,Ordering::Relaxed);let mut output=Vec::<u8>::new();let mut actual=None;let((result,attempts),physical)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||native.allocate_vec_into(request,&mut output,&mut actual,&mut unwind)));let failure=result.unwrap_err();assert_eq!(attempts,1);assert_eq!(physical,(0,0));assert_eq!(failure.primary.as_ref().unwrap().kind,ValueRefusalKind::AllocationFailed);assert_eq!(failure.forwarded_post.as_ref().unwrap().owned().unwrap().message.as_ref(),"post refused");assert_eq!(failure.progress.actual_capacity_bytes,Some(0));assert_eq!(failure.progress.admitted_bytes,native.owned_bytes());assert_eq!(admitted.load(Ordering::Relaxed),native.owned_bytes());assert_eq!(posted.load(Ordering::Relaxed),0);assert!(output.is_empty());assert_eq!(output.capacity(),0);assert!(unwind.is_none());drop(native);close(prior_owner);close(output);close(failure);}).unwrap();assert!(authority.into_port().is_ok());
}
#[test]
fn slot_retains_born_owner_when_original_post_refuses(){
 let port=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(_)=>Ok(()),NativeAllocationEvent::Post{..}=>Err(ValueError::literal(ValueRefusalKind::Canceled,"post refused")),NativeAllocationEvent::Cancel(_)=>panic!("unexpected cancellation")};let mut progress=|_|true;let mut authority=crate::NativeAllocationAuthority::new(eff::Port(port));authority.with_send_loan(&mut (),|port_loan|{let mut native=NativeEncodeControl::new_forwarded(5,&mut progress,port_loan);let mut output=Vec::<u8>::new();let mut unwind=None;let mut actual=None;let failure=native.allocate_vec_into(5,&mut output,&mut actual,&mut unwind).unwrap_err();assert_eq!(output.capacity(),5);assert_eq!(failure.progress.actual_capacity_bytes,Some(output.capacity()));assert_eq!(failure.progress.admitted_bytes,5);assert_eq!(failure.forwarded_post.as_ref().unwrap().owned().unwrap().message.as_ref(),"post refused");assert!(unwind.is_none());drop(native);close(output);close(failure);}).unwrap();assert!(authority.into_port().is_ok());
}

#[test]
fn text_slot_retains_original_backing_on_post_refusal(){
 let port=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(_)=>Ok(()),NativeAllocationEvent::Post{..}=>Err(ValueError::literal(ValueRefusalKind::Canceled,"text post refused")),NativeAllocationEvent::Cancel(_)=>panic!("unexpected cancellation")};let mut progress=|_|true;let mut authority=crate::NativeAllocationAuthority::new(eff::Port(port));authority.with_send_loan(&mut (),|port_loan|{let mut native=NativeEncodeControl::new_forwarded(5,&mut progress,port_loan);let mut output=String::new();let mut unwind=None;let mut actual=None;let failure=native.reserve_text_into(5,&mut output,&mut actual,&mut unwind).unwrap_err();assert!(output.is_empty());assert_eq!(output.capacity(),5);assert_eq!(failure.progress.actual_capacity_bytes,Some(output.capacity()));assert_eq!(failure.forwarded_post.as_ref().unwrap().owned().unwrap().message.as_ref(),"text post refused");assert!(unwind.is_none());drop(native);close(output);close(failure);}).unwrap();assert!(authority.into_port().is_ok());
}

#[test]
fn scoped_quote_and_original_cancel_refusals_survive_together(){
 let original=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(_)=>Ok(()),NativeAllocationEvent::Cancel(_)=>Err(ValueError::literal(ValueRefusalKind::Canceled,"original cancel refused")),NativeAllocationEvent::Post{..}=>panic!("effect was not admitted")};let scoped=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(_)=>Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"scoped quote refused")),_=>panic!("no scoped settlement")};let mut progress=|_|true;let mut original_authority=crate::NativeAllocationAuthority::new(eff::Port(original));let mut scoped_authority=crate::NativeAllocationAuthority::new(eff::Port(scoped));original_authority.with_send_loan(&mut (),|original_loan|scoped_authority.with_send_loan(&mut (),|scoped_loan|{let mut native=NativeEncodeControl::new_forwarded(5,&mut progress,original_loan);native.scoped_allocation=Some(scoped_loan);let mut output=Vec::<u8>::new();let mut unwind=None;let mut actual=None;let failure=native.allocate_vec_into(5,&mut output,&mut actual,&mut unwind).unwrap_err();assert_eq!(failure.scoped_quote.as_ref().unwrap().owned().unwrap().message.as_ref(),"scoped quote refused");assert_eq!(failure.forwarded_cancel.as_ref().unwrap().owned().unwrap().message.as_ref(),"original cancel refused");assert_eq!(failure.progress.actual_capacity_bytes,None);assert_eq!(failure.progress.admitted_bytes,0);assert_eq!(native.owned_bytes(),0);assert_eq!(output.capacity(),0);assert!(unwind.is_none());native.scoped_allocation=None;drop(native);close(failure);}).unwrap()).unwrap();assert!(original_authority.into_port().is_ok());assert!(scoped_authority.into_port().is_ok());
}

#[test]
fn caller_slot_and_original_callback_phase_survive_post_unwind(){
 struct Interrupting;impl crate::NativeAllocationAuthorityPort for Interrupting{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError> where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}fn receive<'reply,'turn,'source>(&mut self,_:&mut (),event:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(_)=>Ok(reply.complete(Ok(()))),NativeAllocationEvent::Post{..}=>{let reply=reply.complete(Err(ValueError::literal(ValueRefusalKind::Canceled,"original post refusal").into()));std::hint::black_box(&reply);panic!("original post interrupted after recording verdict")},_=>panic!("unexpected event")}}fn recover<'reply,'turn,'source>(&mut self,_:&mut (),_:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{Ok(reply.pending())}}
 let mut observe=|_|true;let mut authority=crate::NativeAllocationAuthority::new(Interrupting);authority.with_send_loan(&mut (),|port_loan|{let mut native=NativeEncodeControl::new_forwarded(5,&mut observe,port_loan);let mut output=Vec::<u8>::new();let mut state=None;let mut actual=None;let unwind=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||native.allocate_vec_into(5,&mut output,&mut actual,&mut state)));assert!(unwind.is_err());assert_eq!(output.capacity(),5);let pending=state.as_mut().unwrap();let actual=pending.outcome().actual;assert_eq!(actual,Some(output.capacity()));native.settle_allocation_progress(pending,actual).unwrap();assert!(native.settle_allocation_progress(pending,actual).is_err());let failure=state.take().unwrap().into_outcome().ok().unwrap().into_allocation_failure(0).unwrap();assert_eq!(failure.forwarded_post.as_ref().unwrap().owned().unwrap().message.as_ref(),"original post refusal");assert_eq!(failure.progress.admitted_bytes,5);assert_eq!(failure.progress.actual_capacity_bytes,actual);drop(native);close(output);close(failure);}).unwrap();assert!(authority.into_port().is_ok());
}

#[test]
fn budget_admission_retains_both_authority_verdicts(){
 
 for (forwarded_ok,scoped_ok) in [(true,false),(false,true),(false,false),(true,true)]{let forwarded=|event|match event{NativeAllocationEvent::Admit(_)=>if forwarded_ok{Ok(())}else{Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"forwarded refused"))},_=>panic!("unexpected physical event")};let scoped=|event|match event{NativeAllocationEvent::Admit(_)=>if scoped_ok{Ok(())}else{Err(ValueError::literal(ValueRefusalKind::Canceled,"scoped refused"))},_=>panic!("unexpected physical event")};let mut observer=|_|true;let mut forwarded_authority=crate::NativeAllocationAuthority::new(eff::Port(forwarded));let mut scoped_authority=crate::NativeAllocationAuthority::new(eff::Port(scoped));forwarded_authority.with_send_loan(&mut (),|loan|scoped_authority.with_send_loan(&mut (),|scoped_loan|{let mut control=NativeEncodeControl::new_forwarded(5,&mut observer,loan);control.scoped_allocation=Some(scoped_loan);let mut state=None;control.begin_admission(5,&mut state).unwrap();let result=control.finish_admission(&mut state);assert_eq!(control.owned_bytes(),if forwarded_ok||scoped_ok{5}else{0});if forwarded_ok&&scoped_ok{assert!(result.is_ok())}else{let failure=result.unwrap_err();assert_eq!(failure.forwarded_admission.is_some(),!forwarded_ok);assert_eq!(failure.scoped_admission.is_some(),!scoped_ok);assert_eq!(failure.progress.actual_capacity_bytes,None);assert_eq!(failure.progress.admitted_bytes,if forwarded_ok||scoped_ok{5}else{0});close(failure)}assert!(state.is_none());control.scoped_allocation=None;drop(control)}).unwrap()).unwrap();assert!(forwarded_authority.into_port().is_ok());assert!(scoped_authority.into_port().is_ok());}
}

#[test]
fn admission_recovers_accepted_forwarded_before_scoped_refusal(){
 struct Forwarded;impl crate::NativeAllocationAuthorityPort for Forwarded{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError> where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}fn receive<'reply,'turn,'source>(&mut self,_:&mut (),event:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{match event{NativeAllocationEvent::Admit(_)=>{let reply=reply.complete(Ok(()));std::hint::black_box(&reply);panic!("original admission interrupted")},_=>panic!("unexpected physical event")}}fn recover<'reply,'turn,'source>(&mut self,_:&mut (),_:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{Ok(reply.pending())}}
 let scoped=|event|match event{NativeAllocationEvent::Admit(_)=>Err(ValueError::literal(ValueRefusalKind::Canceled,"scoped refused")),_=>panic!("unexpected physical event")};let mut observer=|_|true;let mut forwarded_authority=crate::NativeAllocationAuthority::new(Forwarded);let mut scoped_authority=crate::NativeAllocationAuthority::new(eff::Port(scoped));forwarded_authority.with_send_loan(&mut (),|loan|scoped_authority.with_send_loan(&mut (),|scoped_loan|{let mut control=NativeEncodeControl::new_forwarded(5,&mut observer,loan);control.scoped_allocation=Some(scoped_loan);let mut slot=None;let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||control.begin_admission(5,&mut slot)));assert!(result.is_err());let state=slot.as_mut().unwrap();control.continue_admission(state).unwrap();assert_eq!(control.owned_bytes(),5);let failure=control.finish_admission(&mut slot).unwrap_err();assert_eq!(failure.progress.admitted_bytes,5);assert_eq!(failure.progress.actual_capacity_bytes,None);assert!(failure.forwarded_admission.is_none());assert_eq!(failure.scoped_admission.as_ref().unwrap().owned().unwrap().message.as_ref(),"scoped refused");control.scoped_allocation=None;drop(control);close(failure);}).unwrap()).unwrap();assert!(forwarded_authority.into_port().is_ok());assert!(scoped_authority.into_port().is_ok());
}

#[test]
fn retained_original_refusal_blocks_outcome_retirement(){let mut vault=crate::NativeAllocationRefusalVault::default();let handle=vault.retain(ValueError::literal(ValueRefusalKind::Canceled,"original refused")).unwrap();let mut outcome=super::super::NativeEncodeAllocationOutcome{request:None,admitted:false,primary:None,forwarded_quote:Some(crate::NativeAllocationRefusal::Retained(handle)),scoped_quote:None,extent_refusal:None,forwarded_refusal:None,scoped_refusal:None,actual:None};assert!(!crate::retirement::RetireOwned::retirement_ready(&outcome));let handle=match outcome.forwarded_quote.take().unwrap(){crate::NativeAllocationRefusal::Retained(handle)=>handle,_=>panic!("expected original retained handle")};let original=vault.take(handle).unwrap();assert_eq!(original.message.as_ref(),"original refused");assert!(crate::retirement::RetireOwned::retirement_ready(&outcome));close(outcome);close(original);}
